#!/usr/bin/env node
import { readFile } from 'node:fs/promises'

// Statuses that mean a task/trial already reached a final state. A recorded
// failure is final too: --resume must not silently retry it.
export const TERMINAL_STATUSES = Object.freeze([
  'passed',
  'partial',
  'failed',
  'blocked_env',
  'succeeded',
  'cancelled',
])

const TERMINAL = new Set(TERMINAL_STATUSES)

export function isTerminalStatus(status) {
  return typeof status === 'string' && TERMINAL.has(status)
}

function taskIdOf(task) {
  if (typeof task === 'string') {
    if (!task) throw new TypeError('task id must be a non-empty string')
    return task
  }
  const id = task?.id
  if (typeof id !== 'string' || !id) {
    throw new TypeError('tasks must be string ids or objects with a non-empty string id')
  }
  return id
}

function keyOf(taskId, trial) {
  return `${taskId}\u0000${trial}`
}

// tasks first, then trial ascending from 1. Any task/trial whose records contain
// a terminal status is dropped, including duplicates: a duplicated terminal
// record can never produce a second run.
export function selectPendingTrials(tasks, trials, records = []) {
  if (!Array.isArray(tasks)) throw new TypeError('tasks must be an array')
  if (!Number.isInteger(trials) || trials < 1) throw new TypeError('trials must be a positive integer')
  if (!Array.isArray(records)) throw new TypeError('records must be an array')

  const finished = new Set()
  for (const record of records) {
    if (!record || typeof record !== 'object' || Array.isArray(record)) {
      throw new Error('each record must be a JSON object with taskId, trial and status')
    }
    if (!isTerminalStatus(record.status)) continue
    const taskId = record.taskId
    const trial = Number(record.trial)
    if (typeof taskId !== 'string' || !taskId || !Number.isInteger(trial) || trial < 1) {
      throw new Error(`terminal record is missing a usable taskId/trial: ${JSON.stringify(record)}`)
    }
    finished.add(keyOf(taskId, trial))
  }

  const pending = []
  const seenTasks = new Set()
  for (const task of tasks) {
    const taskId = taskIdOf(task)
    if (seenTasks.has(taskId)) continue
    seenTasks.add(taskId)
    for (let trial = 1; trial <= trials; trial += 1) {
      if (finished.has(keyOf(taskId, trial))) continue
      pending.push({ taskId, trial })
    }
  }
  return pending
}

// Blank lines are skipped; any unparseable line is a hard error so a damaged
// runs.jsonl can never be silently truncated into a full re-run.
export function parseRunRecords(text, options = {}) {
  if (typeof text !== 'string') throw new TypeError('record text must be a string')
  const source = options.source ?? 'runs.jsonl'
  const records = []
  const lines = text.split(/\r?\n/)
  for (let index = 0; index < lines.length; index += 1) {
    const line = lines[index].trim()
    if (!line) continue
    let parsed
    try {
      parsed = JSON.parse(line)
    } catch (error) {
      throw new Error(`Corrupt JSONL in ${source} at line ${index + 1}: ${error.message}`)
    }
    if (parsed === null || typeof parsed !== 'object' || Array.isArray(parsed)) {
      throw new Error(`Corrupt JSONL in ${source} at line ${index + 1}: expected a JSON object`)
    }
    records.push(parsed)
  }
  return records
}

export async function readRunRecords(runsPath) {
  let text
  try {
    text = await readFile(runsPath, 'utf8')
  } catch (error) {
    if (error.code === 'ENOENT') return []
    throw error
  }
  return parseRunRecords(text, { source: runsPath })
}

