import test from 'node:test'
import assert from 'node:assert/strict'
import { selectPendingTrials, isTerminalStatus, parseRunRecords, TERMINAL_STATUSES } from './resume.mjs'

test('selectPendingTrials returns task order first, trial from 1', () => {
  assert.deepEqual(selectPendingTrials(['a', 'b'], 2), [
    { taskId: 'a', trial: 1 },
    { taskId: 'a', trial: 2 },
    { taskId: 'b', trial: 1 },
    { taskId: 'b', trial: 2 },
  ])
})

test('selectPendingTrials accepts task objects with id and keeps declared order', () => {
  const tasks = [{ id: 'files-02' }, { id: 'code-07' }]
  assert.deepEqual(selectPendingTrials(tasks, 1), [
    { taskId: 'files-02', trial: 1 },
    { taskId: 'code-07', trial: 1 },
  ])
})

test('every declared terminal status is skipped, including failed', () => {
  assert.deepEqual(TERMINAL_STATUSES, ['passed', 'partial', 'failed', 'blocked_env', 'succeeded', 'cancelled'])
  for (const status of TERMINAL_STATUSES) {
    assert.equal(isTerminalStatus(status), true, `${status} must be terminal`)
    const records = [{ taskId: 'a', trial: 1, status }]
    assert.deepEqual(selectPendingTrials(['a'], 2, records), [{ taskId: 'a', trial: 2 }])
  }
})

test('non-terminal statuses running/pending are not skipped', () => {
  for (const status of ['running', 'pending']) {
    assert.equal(isTerminalStatus(status), false, `${status} must stay pending`)
    const records = [{ taskId: 'a', trial: 1, status }]
    assert.deepEqual(selectPendingTrials(['a'], 1, records), [{ taskId: 'a', trial: 1 }])
  }
})

test('a failed trial is not retried but other trials continue', () => {
  const records = [
    { taskId: 'a', trial: 1, status: 'failed' },
    { taskId: 'b', trial: 1, status: 'passed' },
  ]
  assert.deepEqual(selectPendingTrials(['a', 'b'], 2, records), [
    { taskId: 'a', trial: 2 },
    { taskId: 'b', trial: 2 },
  ])
})

test('duplicate terminal records never cause duplicate runs', () => {
  const records = [
    { taskId: 'a', trial: 1, status: 'passed' },
    { taskId: 'a', trial: 1, status: 'failed' },
    { taskId: 'a', trial: 1, status: 'succeeded' },
  ]
  assert.deepEqual(selectPendingTrials(['a'], 2, records), [{ taskId: 'a', trial: 2 }])
  // Non-terminal duplicates must not duplicate the returned work item either.
  const running = [{ taskId: 'a', trial: 1, status: 'running' }, { taskId: 'a', trial: 1, status: 'running' }]
  const pending = selectPendingTrials(['a'], 1, running)
  assert.deepEqual(pending, [{ taskId: 'a', trial: 1 }])
  assert.equal(new Set(pending.map((item) => `${item.taskId}#${item.trial}`)).size, pending.length)
})

test('repeated task ids are not re-expanded', () => {
  assert.deepEqual(selectPendingTrials(['a', 'a'], 1), [{ taskId: 'a', trial: 1 }])
})

test('terminal records with an unusable taskId/trial are rejected', () => {
  assert.throws(() => selectPendingTrials(['a'], 1, [{ taskId: '', trial: 1, status: 'passed' }]), /taskId/)
  assert.throws(() => selectPendingTrials(['a'], 1, [{ status: 'passed' }]), /taskId/)
  assert.throws(() => selectPendingTrials(['a'], 1, [['a', 1]]), /JSON object/)
  assert.throws(() => selectPendingTrials('a', 1), TypeError)
  assert.throws(() => selectPendingTrials(['a'], 0), TypeError)
  assert.throws(() => selectPendingTrials(['a'], 1, {}), TypeError)
})

test('parseRunRecords reads real run rows and skips only blank lines', () => {
  const row = { schemaVersion: 1, taskId: 'a', trial: 1, status: 'failed' }
  const text = `${JSON.stringify(row)}\n\n${JSON.stringify({ ...row, trial: 2, status: 'running' })}\n`
  const records = parseRunRecords(text)
  assert.equal(records.length, 2)
  assert.equal(records[1].status, 'running')
  assert.deepEqual(selectPendingTrials(['a'], 2, records), [{ taskId: 'a', trial: 2 }])
})

test('corrupt JSONL throws with its line number instead of being dropped', () => {
  const row = JSON.stringify({ taskId: 'a', trial: 1, status: 'passed' })
  const text = `${row}\n{ not json\n`
  assert.throws(() => parseRunRecords(text, { source: 'runs.jsonl' }), /Corrupt JSONL in runs.jsonl at line 2/)
  assert.throws(() => parseRunRecords('"scalar"\n'), /expected a JSON object/)
  assert.throws(() => parseRunRecords('[1,2]\n'), /expected a JSON object/)
})

