import { test } from 'node:test'
import assert from 'node:assert/strict'
import { spawn } from 'node:child_process'
import { mkdtemp, mkdir, writeFile, readFile, rm } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

// End-to-end resume check for scripts/eval/run.mjs driven by a recording fake
// CLI. The fake CLI only prints JSONL and appends one log line per invocation,
// so no real provider or model process can be reached: the config declares the
// local `ollama` provider profile, which the runner accepts without any
// credential and never dials because --cli always points at the fake binary.
const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..')
const runScript = join(root, 'scripts/eval/run.mjs')
const datasetPath = join(root, 'evals/tasks.v1.json')

const FAKE_CLI = String.raw`import { appendFileSync } from 'node:fs'
const log = process.env.FAKE_CLI_LOG
if (log) {
  appendFileSync(log, JSON.stringify({ cwd: process.cwd(), dataDir: process.env.PULSE_DATA_DIR ?? null, argv: process.argv.slice(2) }) + '\n')
}
const status = process.env.FAKE_CLI_STATUS || 'succeeded'
process.stdout.write(JSON.stringify({ type: 'text', data: 'fake-cli-ran' }) + '\n')
process.stdout.write(JSON.stringify({
  type: 'result',
  status: status,
  taskOutcome: { status: status === 'succeeded' ? 'accepted' : 'rejected' },
  usage: { inputTokens: 10, outputTokens: 5, completeness: 'complete' },
}) + '\n')
`

function runNode(args, options = {}) {
  return new Promise((resolvePromise) => {
    const child = spawn(process.execPath, args, {
      cwd: options.cwd ?? root,
      env: { ...process.env, ...(options.env ?? {}) },
      stdio: ['ignore', 'pipe', 'pipe'],
    })
    let stdout = ''
    let stderr = ''
    child.stdout.setEncoding('utf8')
    child.stderr.setEncoding('utf8')
    child.stdout.on('data', (chunk) => { stdout += chunk })
    child.stderr.on('data', (chunk) => { stderr += chunk })
    child.on('error', (error) => resolvePromise({ code: 1, stdout, stderr: `${stderr}${error.message}` }))
    child.on('exit', (code) => resolvePromise({ code: code ?? 1, stdout, stderr }))
  })
}

async function setup(seedBuilder) {
  const dataset = JSON.parse(await readFile(datasetPath, 'utf8'))
  const taskId = dataset.tasks[0].id
  const base = await mkdtemp(join(tmpdir(), 'pulse-eval-resume-'))
  const out = join(base, 'out')
  await mkdir(out, { recursive: true })
  const fakeCli = join(base, 'fake-cli.mjs')
  await writeFile(fakeCli, FAKE_CLI)
  const configPath = join(base, 'config.json')
  await writeFile(configPath, JSON.stringify({
    providers: { local: { provider: 'ollama', baseUrl: 'http://127.0.0.1:1' } },
    models: { 'fake-model': { displayName: 'Fake Model', provider: 'local', modelCode: 'fake-model-code', maxContextTokens: 1000 } },
  }, null, 2))
  const logPath = join(base, 'cli.log')
  await writeFile(logPath, '')
  const seedLines = typeof seedBuilder === 'function' ? seedBuilder(taskId) : seedBuilder
  if (seedLines) await writeFile(join(out, 'runs.jsonl'), `${seedLines.join('\n')}\n`)
  return { base, out, fakeCli, configPath, logPath, taskId }
}

function runRow(taskId, trial, status) {
  return JSON.stringify({
    schemaVersion: 1,
    taskId,
    category: 'code',
    trial,
    status,
    usage: { inputTokens: 10, outputTokens: 10, completeness: 'complete' },
  })
}

function runRunner(ctx, { resume = true, env = {} } = {}) {
  return runNode([
    runScript,
    '--dataset', datasetPath,
    '--task', ctx.taskId,
    '--cli', ctx.fakeCli,
    '--config', ctx.configPath,
    '--model', 'fake-model',
    '--out', ctx.out,
    '--trials', '3',
    '--max-total-tokens', '10000000',
    '--auto-approve',
    ...(resume ? ['--resume'] : []),
  ], { env: { FAKE_CLI_LOG: ctx.logPath, ...env } })
}

async function readJsonLines(path) {
  const text = await readFile(path, 'utf8')
  return text.trim().split('\n').filter(Boolean).map((line) => JSON.parse(line))
}

test('--resume skips a succeeded trial, appends pending ones, and keeps artifacts', async () => {
  const ctx = await setup((taskId) => [runRow(taskId, 1, 'succeeded')])
  try {
    const run = await runRunner(ctx)
    assert.equal(run.code, 0, run.stderr)
    const rows = await readJsonLines(join(ctx.out, 'runs.jsonl'))
    assert.deepEqual(rows.map((row) => row.trial), [1, 2, 3])
    assert.equal(rows[0].status, 'succeeded')
    const calls = await readJsonLines(ctx.logPath)
    assert.equal(calls.length, 2)
    assert.ok(calls.every((entry) => entry.argv[0] === 'run'))
    const report = JSON.parse(await readFile(join(ctx.out, 'report.json'), 'utf8'))
    assert.equal(report.tasksRun, 3)
  } finally {
    await rm(ctx.base, { recursive: true, force: true })
  }
})

test('--resume does not retry a failed trial but still runs the missing ones', async () => {
  const ctx = await setup((taskId) => [runRow(taskId, 1, 'failed')])
  try {
    const run = await runRunner(ctx)
    assert.equal(run.code, 0, run.stderr)
    const rows = await readJsonLines(join(ctx.out, 'runs.jsonl'))
    assert.deepEqual(rows.map((row) => row.trial), [1, 2, 3])
    assert.equal(rows.filter((row) => row.status === 'failed').length, 1)
    const calls = await readJsonLines(ctx.logPath)
    assert.equal(calls.length, 2)
  } finally {
    await rm(ctx.base, { recursive: true, force: true })
  }
})

test('--resume collapses duplicate terminal records without extra runs', async () => {
  const ctx = await setup((taskId) => [runRow(taskId, 1, 'succeeded'), runRow(taskId, 1, 'succeeded')])
  try {
    const run = await runRunner(ctx)
    assert.equal(run.code, 0, run.stderr)
    const rows = await readJsonLines(join(ctx.out, 'runs.jsonl'))
    assert.equal(rows.length, 4)
    const calls = await readJsonLines(ctx.logPath)
    assert.equal(calls.length, 2)
  } finally {
    await rm(ctx.base, { recursive: true, force: true })
  }
})

test('--resume rejects a damaged runs.jsonl instead of silently re-running it', async () => {
  const ctx = await setup((taskId) => [runRow(taskId, 1, 'succeeded'), '{not json'])
  try {
    const run = await runRunner(ctx)
    assert.notEqual(run.code, 0)
    assert.match(run.stderr, /Corrupt JSONL/)
    assert.match(run.stderr, /at line 2/)
    assert.equal((await readFile(ctx.logPath, 'utf8')).trim(), '')
    assert.match(await readFile(join(ctx.out, 'runs.jsonl'), 'utf8'), /\{not json/)
  } finally {
    await rm(ctx.base, { recursive: true, force: true })
  }
})

