#!/usr/bin/env node
// End-to-end resume check for scripts/eval/run.mjs.
// The CLI is a dependency stub: every invocation is appended to FAKE_CLI_LOG,
// so the number of real executions is proven from that call log instead of from
// historical runs.jsonl line counts. No provider or network call is made.
import { test } from 'node:test'
import assert from 'node:assert/strict'
import { spawnSync } from 'node:child_process'
import { appendFile, mkdtemp, readFile, writeFile } from 'node:fs/promises'
import { tmpdir } from 'node:os'
import { dirname, join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(dirname(fileURLToPath(import.meta.url)), '../..')
const runScript = join(root, 'scripts/eval/run.mjs')
const datasetPath = join(root, 'evals/tasks.v1.json')

const FAKE_CLI = [
  "import { appendFileSync } from 'node:fs'",
  "const log = process.env.FAKE_CLI_LOG",
  "if (!log) throw new Error('FAKE_CLI_LOG is required')",
  "appendFileSync(log, JSON.stringify({ argv: process.argv.slice(2), cwd: process.cwd(), dataDir: process.env.PULSE_DATA_DIR }) + String.fromCharCode(10))",
  "const emit = (item) => process.stdout.write(JSON.stringify(item) + String.fromCharCode(10))",
  "emit({ type: 'status', data: 'fake-cli-start' })",
  "emit({ type: 'text', data: 'fake-cli-finished' })",
  "emit({ type: 'result', status: 'succeeded', taskOutcome: { status: 'accepted' }, usage: { inputTokens: 12, outputTokens: 7, completeness: 'complete' } })",
  '',
].join('\n')

const CONFIG = {
  models: { 'fake-model': { displayName: 'Fake Model', provider: 'ollama', modelCode: 'fake-1', maxContextTokens: 32000 } },
  providers: { ollama: { provider: 'ollama' } },
}

const lines = (text) => text.split(/\r?\n/).filter(Boolean)
const callLog = async (path) => lines(await readFile(path, 'utf8')).map((line) => JSON.parse(line))

test('run.mjs --resume skips terminal records and never re-invokes the CLI', async () => {
  const base = await mkdtemp(join(tmpdir(), 'pulse-resume-e2e-'))
  const outDir = join(base, 'out')
  const logPath = join(base, 'calls.log')
  const fakeCli = join(base, 'fake-cli.mjs')
  const configPath = join(base, 'config.json')
  await writeFile(fakeCli, FAKE_CLI)
  await writeFile(configPath, JSON.stringify(CONFIG))
  await writeFile(logPath, '')

  const dataset = JSON.parse(await readFile(datasetPath, 'utf8'))
  const task = dataset.tasks[0]
  assert.ok(task && typeof task.id === 'string', 'dataset must expose at least one task id')

  const common = ['--dataset', datasetPath, '--task', task.id, '--cli', fakeCli, '--config', configPath,
    '--model', 'fake-model', '--trials', '1', '--max-total-tokens', '200000', '--auto-approve']
  const run = (extra) => spawnSync(process.execPath, [runScript, ...common, '--out', outDir, ...extra],
    { encoding: 'utf8', env: { ...process.env, FAKE_CLI_LOG: logPath } })

  // 1. First real batch runs the one pending trial through the stub CLI.
  const first = run([])
  assert.equal(first.status, 0, `first run failed: ${first.stderr}`)
  assert.equal(lines(await readFile(logPath, 'utf8')).length, 1, 'stub CLI must be invoked exactly once')

  const runsPath = join(outDir, 'runs.jsonl')
  const firstRecords = lines(await readFile(runsPath, 'utf8')).map((line) => JSON.parse(line))
  assert.equal(firstRecords.length, 1, 'first run must append exactly one record')
  assert.equal(firstRecords[0].taskId, task.id)
  assert.equal(firstRecords[0].status, 'succeeded', 'accepted stub result must map to a terminal status')
  assert.ok(firstRecords[0].grading && typeof firstRecords[0].grading.score === 'number', 'grading summary must be recorded')

  const firstCall = (await callLog(logPath))[0]
  assert.equal(firstCall.argv[0], 'run', 'stub CLI must see the real `run` subcommand')
  assert.ok(firstCall.argv.includes('--cwd'), 'stub CLI must receive --cwd')
  assert.ok(firstCall.argv.includes('--data-dir'), 'stub CLI must receive --data-dir')

  // 2. An existing output directory is still refused without --resume.
  const refused = run([])
  assert.notEqual(refused.status, 0, 'a second non-resume run must fail')
  assert.match(refused.stderr, /Output directory already exists/, 'refusal must name the existing directory')

  // 3. --resume treats the terminal record as finished: zero pending trials and
  //    no additional CLI invocation, while the history stays untouched.
  const resumed = run(['--resume'])
  assert.equal(resumed.status, 0, `resume run failed: ${resumed.stderr}`)
  assert.match(resumed.stdout, /--resume: 1 existing record\(s\), 0 pending of 1/, 'resume must report zero pending trials')
  assert.equal(lines(await readFile(logPath, 'utf8')).length, 1, 'resume must not re-invoke the stub CLI')
  assert.equal(lines(await readFile(runsPath, 'utf8')).length, 1, 'resume must not append a duplicate record')
  const report = JSON.parse(await readFile(join(outDir, 'report.json'), 'utf8'))
  assert.equal(report.tasksRun, 1, 'report must summarize the historical record')
  assert.equal(report.completedRuns, 1, 'report must keep the historical success')

  // 4. A damaged runs.jsonl aborts instead of silently re-running the trial.
  await appendFile(runsPath, 'not-json{\n')
  const corrupt = run(['--resume'])
  assert.notEqual(corrupt.status, 0, 'corrupt JSONL must be a hard error')
  assert.match(corrupt.stderr, /Corrupt JSONL in .*runs\.jsonl at line 2/, 'corrupt JSONL must report its file and line')
  assert.equal(lines(await readFile(logPath, 'utf8')).length, 1, 'corrupt JSONL must abort before invoking the CLI')
})
